css:
/* NO SLIDER ON A PRINTED PAGE.
   `.tblwrap` is `overflow-x:auto`, which on screen gives a
   horizontal scrollbar and on paper simply loses everything to the
   right of the column — the reader cannot scroll a sheet of paper.
   A comparison table has to FIT: fixed layout so the columns share
   the width, and cells that wrap instead of pushing the table wider.
   Scoped to chemistry, whose two-column comparisons are the widest
   tables in the book. */
.subj-chemistry .tblwrap { overflow-x:visible; }
.subj-chemistry .tbl { table-layout:fixed; width:100%; }
.subj-chemistry .tbl th, .subj-chemistry .tbl td
  { overflow-wrap:break-word; word-break:normal; padding:6px 9px;
    vertical-align:top; }
.subj-chemistry .acol .tbl { font-size:15.2px; }
